patch:
diff --git a/repro/windows-cross-drive.js b/repro/windows-cross-drive.js
new file mode 100644
index 0000000..5d4a765
--- /dev/null
+++ b/repro/windows-cross-drive.js
@@ -0,0 +1,83 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * Simulates Windows on any OS: `process.platform` is forced to "win32",
+ * every `require("path")` / `require("node:path")` returns `path.win32`,
+ * and the working directory is "C:\\Project". Then a file on another drive
+ * (F:\foo.js) is checked against a file on the same drive outside the cwd
+ * (C:\Other\foo.js), which is the expected behaviour.
+ *
+ * Usage: node repro/windows-cross-drive.js
+ */
+"use strict";
+
+const Module = require("node:module");
+const path = require("node:path");
+
+const CWD = "C:\\Project";
+
+Object.defineProperty(process, "platform", { value: "win32" });
+process.cwd = () => CWD;
+
+const originalRequire = Module.prototype.require;
+
+Module.prototype.require = function(id, ...args) {
+    if (id === "path" || id === "node:path") {
+        return path.win32;
+    }
+    return originalRequire.call(this, id, ...args);
+};
+
+const { Linter, ESLint } = require("..");
+
+const files = {
+    "same drive, outside cwd (expected: ignored)": "C:\\Other\\foo.js",
+    "different drive (bug: should be ignored)": "F:\\foo.js"
+};
+
+console.log(`cwd = ${CWD}`);
+for (const [label, file] of Object.entries(files)) {
+    console.log(`  path.win32.relative(cwd, ${JSON.stringify(file)}) = ${JSON.stringify(path.win32.relative(CWD, file))}`);
+}
+
+(async () => {
+    let buggy = false;
+
+    console.log("\n--- Linter#verify (flat config, no-undef: error) ---");
+    const linter = new Linter({ configType: "flat" });
+
+    for (const [label, file] of Object.entries(files)) {
+        const messages = linter.verify("foo()", { rules: { "no-undef": "error" } }, file);
+        const linted = messages.some(m => m.ruleId === "no-undef");
+
+        console.log(`${label}: ${file}`);
+        console.log(`  ${linted ? "LINTED" : "ignored"} -> ${JSON.stringify(messages.map(m => m.ruleId ? `${m.ruleId}: ${m.message}` : m.message))}`);
+        if (file.startsWith("F:") && linted) {
+            buggy = true;
+        }
+    }
+
+    console.log("\n--- ESLint (overrideConfigFile: true, i.e. --no-config-lookup) ---");
+    const eslint = new ESLint({
+        cwd: CWD,
+        overrideConfigFile: true,
+        overrideConfig: { rules: { "no-undef": "error" } }
+    });
+
+    for (const [label, file] of Object.entries(files)) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();", { filePath: file, warnIgnored: true });
+
+        console.log(`${label}: ${file}`);
+        console.log(`  isPathIgnored = ${ignored}`);
+        console.log(`  lintText -> ${JSON.stringify(result.messages.map(m => m.ruleId ? `${m.ruleId}: ${m.message}` : m.message))}`);
+        if (file.startsWith("F:") && !ignored) {
+            buggy = true;
+        }
+    }
+
+    console.log(buggy
+        ? "\nBUG REPRODUCED: F:\\foo.js (different drive) is linted instead of ignored."
+        : "\nNot reproduced: F:\\foo.js was ignored.");
+    process.exitCode = buggy ? 1 : 0;
+})();
